// 复数的结构类型定义
typedef struct {
    float a;
    float b;
} cnum;
cnum x, y, z; // 全局变量

// 计算两个复数之和
cnum add(cnum p, cnum q) {
    cnum s;
    s.a = p.a+q.a;
    s.b = p.b+q.b;
    return s;
}

